      </select>
      <Button onClick={() => dirty ? setPendingSwitch({create: true}) : void createArticle()} disabled={Boolean(busy)}>新建文章</Button>
      {state && <span className="text-xs text-muted-foreground">{currentVersionNumber === undefined ? "当前版本" : `当前版本 v${currentVersionNumber}`}</span>}
    </section>
    {pendingSwitch && <section role="alertdialog" aria-label="当前文章有未保存修改" className="space-y-3 rounded-xl border border-border bg-surface p-4">
